// webc/jobs.h — the queue is a table, and the worker is a loop over four statements.
//
// The claim is the interesting part: one conditional UPDATE says "this row is mine now", so two
// workers — in this process or in another — cannot both run it, and a process that dies leaves a
// lease that expires instead of a job nobody will ever retry.
#include <webc/jobs.h>

// `WJob_model` is generated by WEBC_MODEL; the pointer form is what the helpers take.
static const WModel *wc_job_model(void) { return WJob_modelof(); }
static const char *wc_job_table(void) {
  const WModel *m = wc_job_model();
  return m->table ? m->table : "wjobs";
}
// The statements are built from the model's own table name: a queue whose SQL spells the table
// by hand is a queue that stops working the day the model is renamed.
static WQuery *job_sql(Arena *a, const char *fmt, ...) {
  Buf b;
  buf_init(&b, a, 256);
  va_list ap;
  va_start(ap, fmt);
  buf_vprintf(&b, fmt, ap);
  va_end(ap);
  return q_a(a, buf_cstr(&b));
}

static struct {
  WJobKind kinds[WC_JOB_MAX];
  i32 n;
} g_jobs;

void wc_job_register(const WJobKind *k) {
  if (!k || !k->name) return;
  for (i32 i = 0; i < g_jobs.n; i++)
    if (strcmp(g_jobs.kinds[i].name, k->name) == 0) { // a duplicate registration replaces
      g_jobs.kinds[i] = *k;
      return;
    }
  if (g_jobs.n < WC_JOB_MAX) g_jobs.kinds[g_jobs.n++] = *k;
}

const WJobKind *wc_job_find(const char *name) {
  if (!name) return nullptr;
  for (i32 i = 0; i < g_jobs.n; i++)
    if (strcmp(g_jobs.kinds[i].name, name) == 0) return &g_jobs.kinds[i];
  return nullptr;
}

i32 wc_job_kinds(void) { return g_jobs.n; }
const WJobKind *wc_job_kind_at(i32 i) { return i >= 0 && i < g_jobs.n ? &g_jobs.kinds[i] : nullptr; }

// ---------------------------------------------------------------- the table

// The columns a job needs and a migration cannot add later without a default. Written once here
// so a test can install it and `webc migrate` writes the same shape from the model.
bool wc_job_install(void) {
  // The statement is generated from the model, not hand-written: a column that a later version
  // adds here is a column the queue actually has, and the row a `webc migrate` would create is
  // the same row a test creates.
  const char *table = wc_job_model()->table ? wc_job_model()->table : "wjobs";
  str sql = model_sql_create_table(wc_arena_get(), wc_job_model(), table);
  WRes r = db_exec_sql(db_default(), sql.p ? sql.p : "");
  return r.ok;
}

static const char *job_status_name(i32 s) {
  switch (s) {
  case W_JOB_RUNNING: return "running";
  case W_JOB_DONE: return "done";
  case W_JOB_FAILED: return "failed";
  default: return "queued";
  }
}

// ---------------------------------------------------------------- enqueue

bool wc_job_enqueue(const WJobKind *k, str payload, i64 delay_ms) {
  if (!k) return false; // a job that is not registered is not a job
  i64 now = time_ms();
  WQuery *qy = job_sql(wc_arena_get(),
                       "insert into %s (kind, payload, status, attempts, max_attempts, backoff_ms,"
                       " run_at, lease_until, created_at, updated_at)"
                       " values (:kind, :payload, 'queued', 0, :max, :backoff, :run_at, 0, :now, :now)",
                       wc_job_table());
  q_cstr(qy, "kind", k->name);
  if (payload.p && payload.n) q_str(qy, "payload", payload);
  else q_null(qy, "payload");
  q_i64(qy, "max", k->max_attempts > 0 ? k->max_attempts : 3);
  q_i64(qy, "backoff", k->backoff_ms > 0 ? k->backoff_ms : 30000);
  q_i64(qy, "run_at", now + (delay_ms > 0 ? delay_ms : 0));
  q_i64(qy, "now", now);
  WRes r = db_exec(db_default(), qy);
  return r.ok;
}

void wc_job_retry_for(const char *name, i32 max_attempts, i64 backoff_ms) {
  for (i32 i = 0; i < g_jobs.n; i++) {
    if (strcmp(g_jobs.kinds[i].name, name) != 0) continue;
    g_jobs.kinds[i].max_attempts = max_attempts > 0 ? max_attempts : 1;
    g_jobs.kinds[i].backoff_ms = backoff_ms > 0 ? backoff_ms : 1000;
    return;
  }
}

// ---------------------------------------------------------------- one tick
//
// Claim, run, record. A tick is the whole worker body, which is why a test can call it: the job
// is the thing worth testing, not the loop around it.
static WJob *job_claim(i64 now, i64 lease_ms) {
  // Anything whose lease expired is queued again: that is the crash recovery, and it is one
  // statement because the lease is a column.
  Buf reap;
  buf_init(&reap, wc_arena_get(), 200);
  buf_printf(&reap,
             "update %s set status = 'queued', lease_until = 0 where status = 'running'"
             " and lease_until < cast(strftime('%%s','now') as integer) * 1000",
             wc_job_table());
  db_exec_sql(db_default(), buf_cstr(&reap));
  WQuery *qy = q("");
  q_i64(qy, "now", now);
  WJob *j = (WJob *)db_find_where(wc_job_model(),
                                  "status = 'queued' and run_at <= :now order by id limit 1", qy);
  if (!j) return nullptr;
  WQuery *up = job_sql(wc_arena_get(),
                       "update %s set status = 'running', lease_until = :lease, updated_at = :now"
                       " where id = :id and status = 'queued'", wc_job_table());
  q_i64(up, "lease", now + lease_ms);
  q_i64(up, "now", now);
  q_i64(up, "id", j->id);
  WRes r = db_exec(db_default(), up);
  if (!r.ok) return nullptr;
  // `affected` is the claim: with two workers, one of them sees 0 here and moves on, which is
  // the whole of "two processes can share a queue".
  if (r.affected < 1) return nullptr;
  return j;
}

bool wc_job_tick(void) {
  i64 now = time_ms();
  WJob *j = job_claim(now, 5 * 60 * 1000);
  if (!j) return false;
  char kind[64] = {0};
  if (j->kind.p && j->kind.n) snprintf(kind, sizeof kind, "%.*s", (int)j->kind.n, j->kind.p);
  const WJobKind *k = wc_job_find(kind);
  str err = {0};
  if (!k) {
    err = str_lit("no job with that name is registered");
  } else {
    str payload = j->payload ? str_lit(j->payload) : (str){0};
    k->run(k->arg, payload, &err);
  }
  i64 attempts = j->attempts + 1;
  i32 max_attempts = j->max_attempts > 0 ? j->max_attempts : 3;
  i64 backoff = j->backoff_ms > 0 ? j->backoff_ms : 30000;
  bool failed = err.p && err.n;
  WQuery *up = job_sql(wc_arena_get(),
                       "update %s set status = :status, attempts = :att, run_at = :run_at,"
                       " lease_until = 0, last_error = :err, updated_at = :now where id = :id",
                       wc_job_table());
  if (!failed) {
    q_cstr(up, "status", job_status_name(W_JOB_DONE));
    q_null(up, "err");
    q_i64(up, "run_at", now);
  } else if (attempts >= max_attempts) {
    q_cstr(up, "status", job_status_name(W_JOB_FAILED));
    q_str(up, "err", err);
    q_i64(up, "run_at", now);
  } else {
    // Backoff grows with the attempt: 30s, 60s, 120s. Not a formula with a name — an app that
    // wants jitter or a cap calls job_retry() with the numbers it wants.
    i64 wait = backoff << (attempts - 1);
    q_cstr(up, "status", job_status_name(W_JOB_QUEUED));
    q_str(up, "err", err);
    q_i64(up, "run_at", now + wait);
  }
  q_i64(up, "att", attempts);
  q_i64(up, "now", now);
  q_i64(up, "id", j->id);
  db_exec(db_default(), up);
  return true;
}

void wc_job_worker(i32 n) {
  if (n <= 0) n = 1;
  for (i32 i = 0; i < n; i++) {
    wg_spawn(nullptr, nullptr, "job_worker");
  }
}

// ---------------------------------------------------------------- repeats
//
// A repeat is a green task that sleeps and calls. One per registration, no cron parser, and the
// name is the app's function name so a log line says which one.
typedef struct WJobRepeat {
  i64 every_ms;
  void (*fn)(void);
  const char *name;
} WJobRepeat;

static void job_repeat_loop(void *arg) {
  WJobRepeat *r = arg;
  for (;;) {
    wg_sleep_ms(r->every_ms > 0 ? r->every_ms : 1000);
    r->fn();
  }
}

void wc_job_every(i64 every_ms, void (*fn)(void), const char *name) {
  if (!fn) return;
  WJobRepeat *r = wc_alloc(sizeof *r);
  r->every_ms = every_ms > 0 ? every_ms : 1000;
  r->fn = fn;
  r->name = name ? name : "repeat";
  wg_spawn(job_repeat_loop, r, r->name);
}

// ---------------------------------------------------------------- reading

i32 wc_job_pending(void) {
  WQuery *qy = job_sql(wc_arena_get(),
                       "select count(*) as n from %s where status in ('queued','running')",
                       wc_job_table());
  WRes r = db_exec(db_default(), qy);
  if (!r.ok || r.nrows < 1) return 0;
  return (i32)row_i64(&r.rows[0], "n");
}

VecWJob *wc_job_failures(i32 limit) {
  WQuery *qy = q("");
  q_i64(qy, "lim", limit > 0 ? limit : 50);
  return (VecWJob *)db_all_clause_vec(db_default(), wc_job_model(), WC_VECOF_VecWJob,
                                      "where status = 'failed' order by updated_at desc limit :lim",
                                      qy);
}

void wc_job_requeue_failed(i64 id) {
  WQuery *qy = job_sql(wc_arena_get(),
                       "update %s set status = 'queued', attempts = 0, run_at = :now,"
                       " last_error = null where id = :id and status = 'failed'", wc_job_table());
  q_i64(qy, "now", time_ms());
  q_i64(qy, "id", id);
  db_exec(db_default(), qy);
}

void wc_job_prune(i64 older_than_ms) {
  WQuery *qy = job_sql(wc_arena_get(),
                       "delete from %s where status = 'done' and updated_at < :cut", wc_job_table());
  q_i64(qy, "cut", time_ms() - (older_than_ms > 0 ? older_than_ms : 7 * 86400000LL));
  db_exec(db_default(), qy);
}
